begin;
set local app.auvo_sync_write='true';
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public;
select plan(11);
select has_function('pcm','sso_registrar_lista_materiais_mediada',array['uuid','integer','uuid','uuid','text','text'],'criação mediada existe');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values ('17992000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','s179-criar@test.local',crypt('x',gen_salt('bf')),'{}','{}',now(),now());
insert into config.usuarios(user_id,papel,nome,ativo) values ('17992000-0000-4000-8000-000000000001','superadmin','Gestor sintético',true);
insert into pcm.clientes(id,nome,created_by) values ('17992000-0000-4000-8000-000000000002','Cliente A','17992000-0000-4000-8000-000000000001'),('17992000-0000-4000-8000-000000000003','Cliente B','17992000-0000-4000-8000-000000000001');
insert into config.sso_concessoes(usuario_id,acao,cliente_id) values ('17992000-0000-4000-8000-000000000001','material.gerir','17992000-0000-4000-8000-000000000002');
insert into pcm.ordens_servico(id,client_id,numero,titulo,categoria,created_by) values ('17992000-0000-4000-8000-000000000011','17992000-0000-4000-8000-000000000002','S179-CR-A','OS A','corretiva','17992000-0000-4000-8000-000000000001'),('17992000-0000-4000-8000-000000000012','17992000-0000-4000-8000-000000000003','S179-CR-B','OS B','corretiva','17992000-0000-4000-8000-000000000001');
set local request.jwt.claims='{"sub":"17992000-0000-4000-8000-000000000001","role":"authenticated","user_role":"superadmin"}';
set local role authenticated;
select throws_ok($$select pcm.sso_registrar_lista_materiais_mediada('17992000-0000-4000-8000-000000000031',0,'17992000-0000-4000-8000-000000000021','17992000-0000-4000-8000-000000000011','cliente','Material A')$$,'55000','criacao_materiais_bloqueada','gate fechado impede criação');
reset role;
update pcm.sso_criacao_materiais_mediada_gate set habilitado=true where id;
set local role authenticated;
select lives_ok($$select pcm.sso_registrar_lista_materiais_mediada('17992000-0000-4000-8000-000000000031',0,'17992000-0000-4000-8000-000000000021','17992000-0000-4000-8000-000000000011','cliente','Material A')$$,'cria lista autorizada');
select lives_ok($$select pcm.sso_registrar_lista_materiais_mediada('17992000-0000-4000-8000-000000000031',0,'17992000-0000-4000-8000-000000000021','17992000-0000-4000-8000-000000000011','cliente','Material A')$$,'replay idêntico aceito');
select throws_ok($$select pcm.sso_registrar_lista_materiais_mediada('17992000-0000-4000-8000-000000000031',0,'17992000-0000-4000-8000-000000000021','17992000-0000-4000-8000-000000000011','cliente','Outro material')$$,'23505','request_id_conflitante','replay divergente recusado');
select throws_ok($$select pcm.sso_registrar_lista_materiais_mediada('17992000-0000-4000-8000-000000000032',0,'17992000-0000-4000-8000-000000000022','17992000-0000-4000-8000-000000000012','cliente','Material B')$$,'42501','ordem_nao_encontrada_ou_sem_acesso','OS de Cliente não autorizado recusada');
reset role;
select is((select count(*)::integer from pcm.listas_materiais where id='17992000-0000-4000-8000-000000000021'),1,'replay não duplica lista');
select ok(has_function_privilege('authenticated','pcm.sso_registrar_lista_materiais_mediada(uuid,integer,uuid,uuid,text,text)','execute') and not has_function_privilege('authenticated','pcm.sso_registrar_lista_materiais(uuid,integer,uuid,uuid,text,text)','execute') and not has_function_privilege('anon','pcm.sso_registrar_lista_materiais_mediada(uuid,integer,uuid,uuid,text,text)','execute'),'mediadora autenticada e núcleo privado');
select is((select count(*)::integer from audit.events where entity_id='17992000-0000-4000-8000-000000000021' and action='material.lista_criada'),1,'replay mantém um único evento de auditoria');
update config.sso_concessoes set ativa=false where usuario_id='17992000-0000-4000-8000-000000000001' and acao='material.gerir';
set local role authenticated;
select throws_ok($$select pcm.sso_registrar_lista_materiais_mediada('17992000-0000-4000-8000-000000000031',0,'17992000-0000-4000-8000-000000000021','17992000-0000-4000-8000-000000000011','cliente','Material A')$$,'42501','ordem_nao_encontrada_ou_sem_acesso','replay após revogação não revela resultado');
reset role;
select is((select count(*)::integer from pcm.sso_lista_materiais_comandos where request_id='17992000-0000-4000-8000-000000000031'),1,'replay e revogação preservam um único comando');
select * from finish();
rollback;
